"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4108],{60643:e=>{e.exports=JSON.parse('{"functions":[{"name":"AnchorDescendants","desc":"Anchors (or with `reset`, unanchors) `instance` and its descendant parts.\\n\\nPassing a [BasePart] directly operates on just that part; anything else walks\\nits descendants.\\n\\n```lua\\nAnchorDescendants(vehicle) -- freeze it in place\\nAnchorDescendants(vehicle, true) -- restore the original anchoring\\n```","params":[{"name":"instance","desc":"The part or instance to anchor/unanchor","lua_type":"Instance"},{"name":"reset","desc":"Pass `true` to undo a previous call; must be nil or true","lua_type":"true?"}],"returns":[],"function_type":"static","source":{"line":35,"path":"src/Shared/Modules/AnchorDescendants.luau"}}],"properties":[],"types":[],"name":"AnchorDescendants","desc":"Anchors every [BasePart] under an instance, then puts them back exactly as they\\nwere on reset.\\n\\nParts that were already anchored before the call are left alone, and parts this\\nhelper anchored are marked with a `PreviouslyAnchored` attribute. Resetting only\\nunanchors parts carrying that marker, so a model that mixes anchored scenery\\nwith loose physics parts survives a round trip unchanged.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":15,"path":"src/Shared/Modules/AnchorDescendants.luau"}}')}}]);